package com.bank.diag;

import java.math.BigDecimal;

public class Account {
    private final String accountId;
    private BigDecimal balance;
    private final Object lock = new Object();   // monitor for this account

    public Account(String accountId, BigDecimal balance) {
        this.accountId = accountId; this.balance = balance;
    }
    public Object lock() { return lock; }
    public String getAccountId() { return accountId; }
    public void debit(BigDecimal a) { balance = balance.subtract(a); }
    public void credit(BigDecimal a) { balance = balance.add(a); }
}
