package com.bank.diag;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // DELIBERATE deadlock: always locks 'from' then 'to' (inconsistent order).
    public void transfer(Account from, Account to, BigDecimal amount) {
        synchronized (from.lock()) {                  // holds 'from' monitor
            log.info(() -> Thread.currentThread().getName()
                    + " locked " + from.getAccountId() + ", waiting for " + to.getAccountId());
            sleep(100);                               // widen the race window
            synchronized (to.lock()) {                // waits for 'to' monitor
                from.debit(amount);
                to.credit(amount);
                log.info(() -> "Transferred " + amount + " "
                        + from.getAccountId() + "→" + to.getAccountId());
            }
        }
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
