package com.bank.diag;

import java.lang.management.ManagementFactory;
import java.math.BigDecimal;

public class ThreadDumpDemo {
    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", new BigDecimal("250000"));
        TransferService svc = new TransferService();

        String pid = ManagementFactory.getRuntimeMXBean().getName().split("@")[0];
        System.out.println("PID=" + pid + "  →  run:  jstack -l " + pid);

        // Opposite lock orders → deadlock within ~100ms.
        new Thread(() -> svc.transfer(rajesh, priya, new BigDecimal("5000")), "transfer-A").start();
        new Thread(() -> svc.transfer(priya, rajesh, new BigDecimal("3000")), "transfer-B").start();
    }
}
