package com.bank.diag;

import org.junit.jupiter.api.Test;
import java.lang.management.ManagementFactory;
import java.lang.management.ThreadMXBean;
import java.math.BigDecimal;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class DeadlockDetectionTest {
    @Test
    void jvmDetectsTheDeadlockProgrammatically() throws InterruptedException {
        Account a = new Account("SAV2001", new BigDecimal("1000000"));
        Account b = new Account("CUR3001", new BigDecimal("250000"));
        TransferService svc = new TransferService();

        new Thread(() -> svc.transfer(a, b, new BigDecimal("5000")), "transfer-A").start();
        new Thread(() -> svc.transfer(b, a, new BigDecimal("3000")), "transfer-B").start();
        Thread.sleep(500);

        ThreadMXBean bean = ManagementFactory.getThreadMXBean();
        long[] deadlocked = bean.findDeadlockedThreads();    // same info as dump's deadlock section
        assertNotNull(deadlocked);                           // JVM found the cycle
    }
}
